def make_question(slug: str, row: tuple, index: int) -> dict:
    stem, correct, distractors, explanation, difficulty = row
    options = [correct, *distractors]
    # Rotate correct-answer position to avoid a predictable answer key.
    shift = index % 4
    options = options[-shift:] + options[:-shift] if shift else options
    return {
        "subject_slug": "gk-gs", "subcategory_slug": "science", "chapter_slug": slug,
        "question_text": stem, "option_a": options[0], "option_b": options[1],
        "option_c": options[2], "option_d": options[3], "correct_option": "ABCD"[options.index(correct)],
        "explanation": explanation, "difficulty": difficulty, "is_pyq": False,
        "pyq_year": "", "pyq_exam_name": "", "source": REF,
    }

if __name__ == "__main__":
    OUT.mkdir(parents=True, exist_ok=True)
    for slug, rows in DATA.items():
        payload = {"questions": [make_question(slug, row, i) for i, row in enumerate(rows)]}
        path = OUT / f"{slug}_followup.json"
        path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        print(f"{path.name}: {len(rows)} questions")
    for slug, rows in EXTRA.items():
        payload = {"questions": [make_question(slug, row, i + len(DATA.get(slug, []))) for i, row in enumerate(rows)]}
        path = OUT / f"{slug}_quality2.json"
        path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        print(f"{path.name}: {len(rows)} questions")
